import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import { FiMenu, FiX, FiUser, FiLogOut, FiBriefcase, FiHome, FiInfo, FiHelpCircle } from 'react-icons/fi';

const Navbar = () => {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
  };

  return (
    <nav className="bg-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          
          {/* Logo */}
          <Link to="/" className="flex items-center space-x-2">
            <div className="w-10 h-10 bg-gradient-to-br from-green-500 to-green-700 rounded-lg flex items-center justify-center">
              <span className="text-white font-black text-xl">S</span>
            </div>
            <span className="text-xl font-black text-gray-900">Student<span className="text-green-600">Hub</span></span>
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            <Link to="/" className="flex items-center space-x-1 text-gray-700 hover:text-green-600 font-medium transition-colors">
              <FiHome size={18}/>
              <span>Home</span>
            </Link>
            <Link to="/browse" className="flex items-center space-x-1 text-gray-700 hover:text-green-600 font-medium transition-colors">
              <FiBriefcase size={18}/>
              <span>Browse Projects</span>
            </Link>
            <Link to="/how-it-works" className="flex items-center space-x-1 text-gray-700 hover:text-green-600 font-medium transition-colors">
              <FiHelpCircle size={18}/>
              <span>How It Works</span>
            </Link>
            <Link to="/about" className="flex items-center space-x-1 text-gray-700 hover:text-green-600 font-medium transition-colors">
              <FiInfo size={18}/>
              <span>About</span>
            </Link>
          </div>

          {/* Desktop Auth Buttons */}
          <div className="hidden md:flex items-center space-x-4">
            {user ? (
              <div className="relative">
                <button onClick={() => setUserDropdownOpen(!userDropdownOpen)} className="flex items-center space-x-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg transition-all">
                  <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-green-700 rounded-full flex items-center justify-center">
                    <FiUser className="text-white" size={16}/>
                  </div>
                  <span className="font-semibold text-gray-800">{user.name}</span>
                </button>
                
                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-gray-100 py-2 animate-slide-down">
                    <Link to="/dashboard" onClick={() => setUserDropdownOpen(false)} className="block px-4 py-2 text-gray-700 hover:bg-green-50 hover:text-green-600 transition-colors">Dashboard</Link>
                    <Link to="/profile" onClick={() => setUserDropdownOpen(false)} className="block px-4 py-2 text-gray-700 hover:bg-green-50 hover:text-green-600 transition-colors">Profile</Link>
                    <hr className="my-2"/>
                    <button onClick={handleLogout} className="w-full text-left px-4 py-2 text-red-600 hover:bg-red-50 transition-colors flex items-center space-x-2">
                      <FiLogOut size={16}/>
                      <span>Logout</span>
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <>
                <Link to="/login" className="px-4 py-2 text-gray-700 hover:text-green-600 font-semibold transition-colors">Login</Link>
                <Link to="/register" className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-semibold transition-all shadow-md hover:shadow-lg">Sign Up</Link>
              </>
            )}
          </div>

          {/* Mobile Menu Button */}
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="md:hidden p-2 text-gray-700 hover:text-green-600 transition-colors">
            {mobileMenuOpen ? <FiX size={24}/> : <FiMenu size={24}/>}
          </button>
        </div>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="md:hidden py-4 border-t border-gray-100 animate-slide-down">
            <div className="flex flex-col space-y-4">
              <Link to="/" onClick={() => setMobileMenuOpen(false)} className="flex items-center space-x-2 text-gray-700 hover:text-green-600 font-medium transition-colors">
                <FiHome size={18}/>
                <span>Home</span>
              </Link>
              <Link to="/browse" onClick={() => setMobileMenuOpen(false)} className="flex items-center space-x-2 text-gray-700 hover:text-green-600 font-medium transition-colors">
                <FiBriefcase size={18}/>
                <span>Browse Projects</span>
              </Link>
              <Link to="/how-it-works" onClick={() => setMobileMenuOpen(false)} className="flex items-center space-x-2 text-gray-700 hover:text-green-600 font-medium transition-colors">
                <FiHelpCircle size={18}/>
                <span>How It Works</span>
              </Link>
              <Link to="/about" onClick={() => setMobileMenuOpen(false)} className="flex items-center space-x-2 text-gray-700 hover:text-green-600 font-medium transition-colors">
                <FiInfo size={18}/>
                <span>About</span>
              </Link>
              
              <hr className="my-2"/>
              
              {user ? (
                <>
                  <Link to="/dashboard" onClick={() => setMobileMenuOpen(false)} className="block px-4 py-2 bg-gray-100 rounded-lg text-gray-700 hover:bg-green-50 hover:text-green-600 font-medium transition-colors">Dashboard</Link>
                  <Link to="/profile" onClick={() => setMobileMenuOpen(false)} className="block px-4 py-2 bg-gray-100 rounded-lg text-gray-700 hover:bg-green-50 hover:text-green-600 font-medium transition-colors">Profile</Link>
                  <button onClick={handleLogout} className="w-full text-left px-4 py-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 font-medium transition-colors flex items-center space-x-2">
                    <FiLogOut size={16}/>
                    <span>Logout</span>
                  </button>
                </>
              ) : (
                <>
                  <Link to="/login" onClick={() => setMobileMenuOpen(false)} className="block px-4 py-2 bg-gray-100 rounded-lg text-gray-700 hover:bg-green-50 hover:text-green-600 font-medium transition-colors text-center">Login</Link>
                  <Link to="/register" onClick={() => setMobileMenuOpen(false)} className="block px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-semibold transition-all text-center">Sign Up</Link>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
